/** Renders `src/generated/assets.ts`: one `with { type: 'file' }` import per built file. */
import { readdir } from 'node:fs/promises'
import { join, relative, sep } from 'node:path'

export const PACKAGE_DIR = join(import.meta.dir, '..')
export const DEFAULT_DIST = join(PACKAGE_DIR, 'dist')
export const GENERATED_MODULE = join(PACKAGE_DIR, 'src', 'generated', 'assets.ts')

const HEADER = [
  '// Generated by `bun run build` (scripts/build.ts). Do not edit.',
  '// The committed version is the "not built" stub; `bun run clean` restores it.',
].join('\n')

/** The stub committed to the repo: no dashboard built. */
export function renderStubModule(): string {
  return `${HEADER}\n\nexport const EMBEDDED_ASSETS: ${LIST_TYPE} = undefined\n`
}

const LIST_TYPE = 'ReadonlyArray<readonly [string, string]> | undefined'

const toPosix = (path: string): string => path.split(sep).join('/')

/** A single-quoted JS string literal (the repo's Biome style). */
export const quote = (value: string): string => `'${value.replace(/\\/g, '\\\\').replace(/'/g, "\\'")}'`

/** `files` are paths below `distDir`; imports are written relative to the module's directory. */
export function renderAssetsModule(files: readonly string[], distDir: string, moduleDir: string): string {
  const sorted = [...files].map(toPosix).sort()
  const imports = sorted.map((file, i) => {
    let spec = toPosix(relative(moduleDir, join(distDir, file)))
    if (!spec.startsWith('.')) spec = `./${spec}`
    return `import f${i} from ${quote(spec)} with { type: 'file' }`
  })
  const entries = sorted.map((file, i) => `  [${quote(file)}, f${i}],`)
  return [
    // The built files are plain JS/CSS/fonts with no type declarations.
    '// @ts-nocheck',
    HEADER,
    ...imports,
    '',
    `export const EMBEDDED_ASSETS: ${LIST_TYPE} = [`,
    ...entries,
    ']',
    '',
  ].join('\n')
}

/** Every file below `dir`, as POSIX paths relative to it. */
export async function listFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { recursive: true, withFileTypes: true })
  return entries
    .filter((entry) => entry.isFile())
    .map((entry) => toPosix(relative(dir, join(entry.parentPath, entry.name))))
    .sort()
}
